using System;using System.Linq;using System.Drawing;using System.Collections.Generic;
namespace GearLab {
 public static class MicroPreset {
  public const string Source="https://www.sweepdynamics.com/products/7960572428322";
  public static Parameters Starter(){var p=new Parameters();Configure(p);p.AutoFit=true;Engine.FitOverall(p);return p;}
  public static void Configure(Parameters p){p.Kind=0;p.CycloidLayout=1;p.MotorPreset=5;p.RingOutput=true;p.IntegratedRing=true;p.RingBridge=0;p.Ratio=20;p.Overall=42;p.Wall=3;p.Radius=17;p.Roller=2;p.Eccentric=.4;p.Clearance=.06;p.Web=.8;p.Discs=2;p.Thickness=3.5;p.DiscGap=.3;p.OutputPins=6;p.OutputPin=5;p.OutputRadius=10.76;p.BearingSimulation=true;p.BearingInner=8;p.Bore=12;p.BearingWidth=3.5;p.BallDiameter=1.2;p.BallCount=9;p.MotorFrame=42.3;p.MotorMount=31;p.MotorPilot=22;p.MotorHole=3.3;p.MotorLength=39;p.Shaft=5;p.ModelCover=4;p.ModelFlange=2;p.ModelGap=.15;p.ModelBolt=3;p.ModelBoltCount=6;p.ModelShaftExtension=2;p.ModelInputBearingD=13;p.ModelInputBearingB=4;p.ModelCaseInner=30;p.ModelCaseOuter=37;p.ModelCaseBearingB=4;p.ModelRollerAxle=1;p.MicroFrontExtension=.5;p.MicroJournal=7;p.MicroRollerLength=10;p.MicroAdapterHeight=5;}
  public static double BodyHeight(Parameters p){return 2*p.ModelCover+2*p.ModelCaseBearingB+p.Discs*Math.Max(p.Thickness,p.BearingWidth)+(p.Discs-1)*p.DiscGap+4*p.ModelGap+p.ModelBolt*.7;}
 }
 public sealed partial class CadBuilder {
  CadLoop MicroSquare(double size){double h=size/2,chamfer=Math.Min(2.5,size*.06);return CadLoop.Polygon(new[]{new PointF((float)(-h+chamfer),(float)-h),new PointF((float)(h-chamfer),(float)-h),new PointF((float)h,(float)(-h+chamfer)),new PointF((float)h,(float)(h-chamfer)),new PointF((float)(h-chamfer),(float)h),new PointF((float)(-h+chamfer),(float)h),new PointF((float)-h,(float)(h-chamfer)),new PointF((float)-h,(float)(-h+chamfer))});}
  void MicroFastener(string code,string label,double x,double y,double seat,double length,double diameter){var bolt=Part(code,label,"fastener",Color.FromArgb(54,64,75));bolt.Sections.Add(new CadSection(seat-length,seat,C(x,y,diameter/2),null));bolt.Sections.Add(new CadSection(seat,seat+.5,C(x,y,diameter*.92),null));bolt.Sections.Add(new CadSection(seat+.5,seat+diameter*.7,C(x,y,diameter*.92),new[]{CadLoop.Polygon(Hex(x,y,diameter*2/3))}));bolt.Note="Условный винт с шестигранным гнездом, без резьбы. Головка утоплена заподлицо; длина рассчитана для этой компоновки.";}
  void MicroCycle(){
   if(!p.RingOutput||p.Discs!=2||!p.BearingSimulation)throw new Exception("Micro: нужны два диска, выход наружного кольца и размеры подшипников.");
   double g=p.ModelGap,t=p.ModelCover,layer=Math.Max(p.Thickness,p.BearingWidth),packet=2*layer+p.DiscGap,outer=p.Radius+p.Roller/2+p.Wall,largeD=p.ModelCaseInner>0?p.ModelCaseInner:30,largeOD=p.ModelCaseOuter>0?p.ModelCaseOuter:largeD+7,largeB=p.ModelCaseBearingB,hubR=largeD/2;
   double rear=t+g,rearEnd=rear+largeB,work=rearEnd+g,end=work+packet,front=end+g,frontEnd=front+largeB,topZ=frontEnd+g+.7*p.ModelBolt,top=topZ+t,rollerBottom=work+(packet-p.MicroRollerLength)/2,rollerTop=rollerBottom+p.MicroRollerLength,boltHead=.7*p.ModelBolt,nutH=.8*p.ModelBolt,nutAF=p.ModelBolt*1.833333;
   if(p.MicroJournal<=p.Shaft+2*p.Web||p.MicroJournal+2*p.Eccentric>=p.BearingInner||p.ModelInputBearingD<=p.MicroJournal)throw new Exception("Micro: проверьте Ø шейки входа, моторного вала и эксцентрика. Шейка должна помещаться в опоре и внутри смещённой шейки диска.");
   if(p.ModelInputBearingB>t+largeB||p.ModelInputBearingB>largeB||p.Bore<=p.BearingInner)throw new Exception("Micro: входные опоры не помещаются по оси либо неверны размеры подшипника диска.");
   if(largeOD<=largeD||largeOD/2+p.Web>=outer||hubR<=p.OutputRadius+Math.Max(p.OutputPin/2+Fit,nutAF/Math.Sqrt(3)+Fit)+p.Web)throw new Exception("Micro: крупная опора/ступица не вмещает пальцы и гайки. Уточните d/D опоры, габарит или радиус пальцев.");
   if(p.OutputRadius-nutAF/Math.Sqrt(3)-Fit<=p.ModelInputBearingD/2+p.Web)throw new Exception("Micro: карманы гаек пересекают центральную опору или оставляют слишком тонкую перемычку.");
   if(p.MicroRollerLength<packet||rollerBottom<t||rollerTop>topZ||p.OutputPin<=p.ModelBolt+2*Fit)throw new Exception("Micro: длина втулок должна перекрывать оба диска и помещаться между плитами; Ø втулки должен быть больше болта.");
   if(t<=Math.Max(nutH,boltHead)+g||hubR+g>=p.Radius-p.Roller/2)throw new Exception("Micro: увеличьте толщину плит либо уменьшите ступицу крупной опоры относительно кольца зацепов.");
   if(p.MotorFrame>0&&p.MicroAdapterHeight<2+p.ModelShaftExtension+g)throw new Exception("Micro: для моторного бурта и выступа входа нужна высота адаптера не менее "+Engine.F(2+p.ModelShaftExtension+g)+" мм. Без мотора можно задать 0.");
   if(p.MotorFrame>0&&p.MotorMount+p.MotorHole+2*p.Web>2*outer)throw new Exception("Micro: отверстия NEMA не помещаются на квадратном основании.");
   if(p.IntegratedRing&&!IntegratedRing.ClearsBridges(r,72))throw new Exception("Micro: диск задевает связки зацепов. Уменьшите ширину связки или эксцентриситет.");
   Color plastic=Color.FromArgb(221,103,39);var pins=Positions(p.OutputPins,p.OutputRadius,0);var ringPins=Positions(r.Pins,p.Radius,0);var motor=MotorPositions();var square=MicroSquare(2*outer);var basePart=Part("MICRO_FIXED_BASE","Micro: квадратное основание и ступица NEMA 17","fixed",plastic);
   double motorSeat=t-boltHead;var levels=new[]{-p.MicroAdapterHeight,0.0,Math.Min(nutH,motorSeat),Math.Max(nutH,motorSeat),t,rollerBottom,rearEnd}.Distinct().OrderBy(z=>z).ToArray();
   for(int j=0;j<levels.Length-1;j++){double a=levels[j],b=levels[j+1];if(b-a<1e-7)continue;bool adapter=a<0,plate=a<t;var holes=new List<CadLoop>{C(0,0,adapter?Math.Max(hubR,p.MotorPilot/2+g):p.ModelInputBearingD/2)};
    if(!adapter){foreach(var v in pins){if(a<nutH-1e-7)holes.Add(CadLoop.Polygon(Hex(v.X,v.Y,nutAF+2*Fit)));else holes.Add(C(v.X,v.Y,a>=rollerBottom-1e-7?p.OutputPin/2+Fit:(p.ModelBolt+2*Fit)/2));}}
    if(plate)holes.AddRange(At(motor,!adapter&&a>=motorSeat-1e-7?p.ModelBolt*1.84+2*Fit:Math.Max(p.MotorHole,p.ModelBolt+2*Fit)));
    basePart.Sections.Add(new CadSection(a,b,adapter||plate?square:C(0,0,hubR),holes));
   }
   basePart.Note="Самостоятельная параметрическая компоновка. Квадратное основание с фасками, карманы гаек, моторный адаптер; нижний габарит задаёт высота адаптера.";
   var topPart=Part("MICRO_FIXED_FRONT","Micro: круглая неподвижная торцевая плита","fixed",plastic);double bore=p.ModelInputBearingD/2;var frontLevels=new[]{front,rollerTop,frontEnd+g,topZ,top-boltHead,top}.Distinct().OrderBy(z=>z).ToArray();for(int j=0;j<frontLevels.Length-1;j++){double a=frontLevels[j],b=frontLevels[j+1];var holes=new List<CadLoop>{C(0,0,a>=frontEnd+g-1e-7?(p.MicroJournal+2*Fit)/2:bore)};holes.AddRange(At(pins,a<rollerTop-1e-7?p.OutputPin+2*Fit:a>=top-boltHead-1e-7?p.ModelBolt*1.84+2*Fit:p.ModelBolt+2*Fit));topPart.Sections.Add(new CadSection(a,b,C(0,0,a>=topZ-1e-7?outer-.5:hubR),holes));}
   var shell=Part("MICRO_CASE_WALL","Micro: вращающийся корпус "+(p.IntegratedRing?"со встроенными зацепами":"с отдельными роликами"),"housing",plastic);var pinHoles=At(ringPins,p.ModelRollerAxle);Action<double,double,CadLoop,bool> section=(a,b,hole,axles)=>shell.Sections.Add(new CadSection(a,b,C(0,0,outer),new[]{hole}.Concat(axles?pinHoles:new CadLoop[0])));
   section(rear,rearEnd,C(0,0,largeOD/2),false);section(rearEnd,work,C(0,0,hubR+g),!p.IntegratedRing);section(work,end,p.IntegratedRing?IntegratedRing.Opening(r):C(0,0,p.Radius+p.Roller/2+p.Clearance),false);section(end,front,C(0,0,hubR+g),!p.IntegratedRing);section(front,frontEnd,C(0,0,largeOD/2),false);section(frontEnd,topZ-g,C(0,0,hubR+g),false);
   shell.Note="Выход — корпус; крупные опоры стоят по краям рабочего пакета. Зацепы объединены только со средним осевым поясом, посадки опор сохранены круглыми.";
   Bearing("INPUT_REAR_BEARING","Micro: задняя опора 7×13×4",0,0,p.MicroJournal,p.ModelInputBearingD,0,p.ModelInputBearingB);Bearing("INPUT_FRONT_BEARING","Micro: передняя опора 7×13×4",0,0,p.MicroJournal,p.ModelInputBearingD,front,p.ModelInputBearingB);
   Bearing("CASE_BEARING_1","Micro: нижняя опора корпуса",0,0,largeD,largeOD,rear,largeB);Bearing("CASE_BEARING_2","Micro: верхняя опора корпуса",0,0,largeD,largeOD,front,largeB);
   var shaft=Part("ECCENTRIC_SHAFT","Micro: полый эксцентриковый входной вал","shaft",steel);double last=-p.ModelShaftExtension;for(int j=0;j<2;j++){double x=j==0?p.Eccentric:-p.Eccentric,z=work+j*(layer+p.DiscGap),bearingZ=z+(layer-p.BearingWidth)/2;if(bearingZ>last)shaft.Sections.Add(new CadSection(last,bearingZ,C(0,0,p.MicroJournal/2),new[]{C(0,0,p.Shaft/2)}));shaft.Sections.Add(new CadSection(bearingZ,bearingZ+p.BearingWidth,C(x,0,p.BearingInner/2),new[]{C(0,0,p.Shaft/2)}));last=bearingZ+p.BearingWidth;var holes=new List<CadLoop>{C(x,0,p.Bore/2)};holes.AddRange(pins.Select(v=>C(v.X+x,v.Y,r.Hole/2)));Extrude("CYCLOID_DISC_"+(j==0?"A":"B"),"Micro: циклоидальный диск "+(j==0?"A":"B"),"gear",j==0?Color.FromArgb(186,194,204):Color.FromArgb(142,155,170),CadLoop.Polygon(Engine.Transform(r.Profile,x,0,j==0?0:-Math.PI/r.Lobes)),z+(layer-p.Thickness)/2,p.Thickness,holes.ToArray());Bearing("ECCENTRIC_BEARING_"+(j+1),"Micro: опора диска",x,0,p.BearingInner,p.Bore,bearingZ,p.BearingWidth);}
   shaft.Sections.Add(new CadSection(last,top+p.MicroFrontExtension,C(0,0,p.MicroJournal/2),new[]{C(0,0,p.Shaft/2)}));shaft.Note="Внешняя шейка опор отличается от Ø моторного вала. Полость под вал мотора; способ фиксации и реальная длина зацепления не назначены.";
   double tieLength=Math.Ceiling((top-boltHead+.1)/5)*5;if(p.MotorFrame>0&&p.OutputRadius-p.ModelBolt/2<p.MotorPilot/2&&top-boltHead-tieLength<-p.MicroAdapterHeight+2+g)throw new Exception("Micro: стяжки заходят в зону моторного бурта. Увеличьте адаптер или толщину плит; длину реального крепежа уточнить отдельно.");foreach(var v in pins){Tube("FIXED_HOLLOW_PIN","Micro: центральная втулка на M3","pin",steel,v.X,v.Y,p.OutputPin,p.ModelBolt,rollerBottom,p.MicroRollerLength);MicroFastener("FRAME_TIE_ROD","Micro: стяжной винт M3×"+Engine.F(tieLength),v.X,v.Y,top-boltHead,tieLength,p.ModelBolt);Nut("FRAME_NUT",v.X,v.Y,0,p.ModelBolt);}
   foreach(var v in motor){double length=Math.Ceiling((p.MicroAdapterHeight+motorSeat+3)/2)*2;MicroFastener("MOTOR_SCREW","Micro: винт NEMA M3×"+Engine.F(length),v.X,v.Y,motorSeat,length,p.ModelBolt);}
   if(!p.IntegratedRing)foreach(var v in ringPins){Tube("RING_ROLLER","Micro: отдельный ролик кольца","roller",steel,v.X,v.Y,p.Roller,p.ModelRollerAxle,work,packet);Tube("ROLLER_AXLE","Micro: ось ролика кольца","pin",steel,v.X,v.Y,p.ModelRollerAxle,0,rearEnd,front-rearEnd);}
   foreach(var part in model.Parts.Where(q=>q.Reference))foreach(var s in part.Sections){s.Bottom-=p.MicroAdapterHeight;s.Top-=p.MicroAdapterHeight;}
   model.Notes.Add("Micro — самостоятельная компоновка по общедоступному референсу "+MicroPreset.Source+". Закрытые STEP/STL оригинала не использовались; совпадение внутренних размеров не заявляется.");
   model.Notes.Add("Референс публикует 20:1 и 42×42×26 мм; наш номинальный пакет без адаптера/мотора и выступа снизу: "+Engine.F(2*outer)+" × "+Engine.F(2*outer)+" × "+Engine.F(top)+" мм. Полный размер с адаптером, валом и мотором показан отдельно.");
   model.Notes.Add("По прежнему ТЗ и интерпретации фото принята схема с вращающимся корпусом; авторский чертёж референса не доступен. Основание, верхняя плита и центральные втулки закреплены. Вращается корпус; два диска имеют противоположные эксцентрики. Размеры опор по открытому BOM; шарики/дорожки не воспроизводятся.");
   model.Notes.Add("Длины винтов рассчитаны для этой компоновки: стяжки M"+Engine.F(p.ModelBolt)+"×"+Engine.F(tieLength)+"; крепление мотора зависит от высоты адаптера. Они могут отличаться от M3×20 / M3×8 референса. Не переносить заявленные оригиналом момент, КПД или люфт на эту модель.");
  }
 }
}
